// fetch wrapper with stale-while-revalidate
async function fetchWithCache(url) {
  const cache = await caches.open('chat-v1');
  const cached = await cache.match(url);
  const response = await fetch(url);
  cache.put(url, response.clone());
  return cached || response;
}

// WebSocket wrapper with exponential backoff
class WSWrapper {
  constructor(url) {
    this.url = url;
    this.queue = [];
    this.reconnect(1000);
  }
  reconnect(delay) {
    this.ws = new WebSocket(this.url);
    this.ws.onclose = () => setTimeout(() => this.reconnect(Math.min(delay * 2, 30000)), delay);
    this.ws.onopen = () => this.queue.forEach(msg => this.ws.send(msg));
  }
  send(msg) { this.ws.readyState === 1 ? this.ws.send(msg) : this.queue.push(msg); }
}

// Patch applier with dedup and ordering
function applyPatch(root, patch) {
  const existing = new Map([...root.querySelectorAll('[data-id]')].map(el => [el.dataset.id, el]));
  patch.sort((a, b) => a.seq - b.seq).forEach(item => {
    if (!existing.has(item.id)) {
      root.appendChild(createMessageEl(item));
    }
  });
}
```

